def compare_values(a, b, c):
    values = [a, b, c]
    return {
        'max': max(values),
        'min': min(values),
        'average': sum(values) / len(values)
    }

print(compare_values(10, 25, 5))

def summarize_inventory(item_name, quantity_in_stock, unit_price):
    total_value = quantity_in_stock * unit_price
    status = 'In Stock' if quantity_in_stock > 0 else 'Out of Stock'
    return {
        'item': item_name,
        'total_value': total_value,
        'status': status
    }

print(summarize_inventory('Laptop', 12, 850))

def sum_digits(n, accumulator=0):
    if n == 0:
        return accumulator
    return sum_digits(n // 10, accumulator + n % 10)

print(sum_digits(1234))
